begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('authenticated','public.complete_user_mfa_reset(uuid,uuid,integer,text)','EXECUTE'),'Browser cannot forge reset completion/audit');
select ok(not has_function_privilege('anon','public.complete_user_mfa_reset(uuid,uuid,integer,text)','EXECUTE'),'Anon denied');
select ok(has_function_privilege('service_role','public.complete_user_mfa_reset(uuid,uuid,integer,text)','EXECUTE'),'Server-only completion');
insert into public.organizations(id,legal_name)values('a6102900-0000-4000-8000-000000000001','MFA QA A'),('a6102900-0000-4000-8000-000000000002','MFA QA B');
insert into auth.users(id,email)select ('b6102900-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'mfa-sql-'||n||'@example.invalid'from generate_series(1,4)n;
insert into public.profiles(id,organization_id,full_name,role_key)select id,
 case when email='mfa-sql-4@example.invalid' then 'a6102900-0000-4000-8000-000000000002'::uuid else 'a6102900-0000-4000-8000-000000000001'::uuid end,
 'Synthetic user',case when email='mfa-sql-3@example.invalid' then 'operator' else 'admin' end from auth.users where email like 'mfa-sql-%@example.invalid';
insert into auth.sessions(id,user_id,created_at,updated_at,aal)select id,id,now(),now(),'aal2' from auth.users where email like 'mfa-sql-%@example.invalid';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000003','b6102900-0000-4000-8000-000000000002',1,'complete')$$,'42501','MFA recovery unavailable.','Permission required');
select throws_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-000000000004',1,'complete')$$,'42501','MFA recovery unavailable.','Cross tenant denied');
select throws_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-999999999999',1,'complete')$$,'42501','MFA recovery unavailable.','Missing target denied');
select throws_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-000000000001',1,'complete')$$,'22023','Invalid MFA recovery completion.','Self-reset cannot destroy executor AAL2');
select throws_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-000000000002',-1,'complete')$$,'22023','Invalid MFA recovery completion.','Invalid counts denied');
select lives_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-000000000002',2,'complete')$$,'Server completes reset');
select is((select count(*)::int from auth.sessions where user_id='b6102900-0000-4000-8000-000000000002'),0,'All target sessions removed');
select is((select count(*)::int from auth.sessions where user_id='b6102900-0000-4000-8000-000000000001'),1,'Executor session preserved');
select is((select status from public.profiles where id='b6102900-0000-4000-8000-000000000002'),'active','Target profile stays active');
select is((select role_key from public.profiles where id='b6102900-0000-4000-8000-000000000002'),'admin','Target role preserved');
select ok(exists(select 1 from public.audit_log where action='USER_MFA_RESET' and actor_user_id='b6102900-0000-4000-8000-000000000001' and entity_id='b6102900-0000-4000-8000-000000000002' and organization_id='a6102900-0000-4000-8000-000000000001' and changes='{"removed_factor_count":{"new":2}}'::jsonb and context='{"source":"user_administration","outcome":"complete"}'::jsonb),'Audit is exact and sanitized');
select set_config('request.jwt.claims','{"sub":"b6102900-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2","session_id":"b6102900-0000-4000-8000-000000000002"}',true);
select ok(not private.current_user_has_aal2(),'Old signed AAL2 JWT is no longer trusted');
select is((select count(*)::int from public.current_user_permissions()),0,'Old session has no permissions');
select set_config('request.jwt.claims','{"sub":"b6102900-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","session_id":"b6102900-0000-4000-8000-000000000001"}',true);
select ok(private.current_user_has_aal2(),'Executor remains AAL2');
select set_config('request.jwt.claims','{"sub":"b6102900-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","session_id":"b6102900-0000-4000-8000-000000000001"}',true);
select ok(not private.current_user_has_aal2(),'AAL1 never passes');
insert into auth.sessions(id,user_id,created_at,updated_at,aal)values('c6102900-0000-4000-8000-000000000002','b6102900-0000-4000-8000-000000000002',now(),now(),'aal1');
select set_config('request.jwt.claims','{"sub":"b6102900-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2","session_id":"c6102900-0000-4000-8000-000000000002"}',true);
select ok(not private.current_user_has_aal2(),'JWT cannot elevate a server AAL1 session');
update auth.sessions set aal='aal2' where id='c6102900-0000-4000-8000-000000000002';
select ok(private.current_user_has_aal2(),'New verified Auth session passes');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.complete_user_mfa_reset('b6102900-0000-4000-8000-000000000001','b6102900-0000-4000-8000-000000000002',0,'complete')$$,'Zero-factor completion is controlled');
select is((select count(*)::int from auth.sessions where user_id='b6102900-0000-4000-8000-000000000002'),0,'Idempotent completion still revokes sessions');
select is((select count(*)::int from auth.sessions where user_id='b6102900-0000-4000-8000-000000000004'),1,'Other tenant sessions untouched');
select is((select count(*)::int from public.audit_log where action='USER_MFA_RESET'),2,'Every completion audited');
select * from finish();
rollback;
